import { useState, useEffect } from 'react';

export function useDebounce<T>(value: T, delayMs: number = 300): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedValue(value);
    }, delayMs);

    // Clean up timeout if value changes before delay expires
    return () => {
      clearTimeout(timer);
    };
  }, [value, delayMs]);

  return debouncedValue;
}

import { useSyncExternalStore } from 'react';

function subscribe(callback: () => void) {
  window.addEventListener('online', callback);
  window.addEventListener('offline', callback);
  return () => {
    window.removeEventListener('online', callback);
    window.removeEventListener('offline', callback);
  };
}

function getSnapshot(): boolean {
  return navigator.onLine;
}

function getServerSnapshot(): boolean {
  return true; // Default assumption during Server-Side Rendering
}

export function useOnlineStatus(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

type AgentStatus = 'idle' | 'executing' | 'awaiting_approval' | 'completed' | 'failed';

interface AgentState {
  status: AgentStatus;
  activeTool: string | null;
  approvalPayload: any | null;
  error: string | null;
}

type AgentAction =
  | { type: 'START_TOOL'; toolName: string }
  | { type: 'REQUIRE_APPROVAL'; toolName: string; payload: any }
  | { type: 'APPROVE_AND_RESUME' }
  | { type: 'COMPLETE' }
  | { type: 'FAIL'; error: string };

function agentReducer(state: AgentState, action: AgentAction): AgentState {
  switch (action.type) {
    case 'START_TOOL':
      return { status: 'executing', activeTool: action.toolName, approvalPayload: null, error: null };
    case 'REQUIRE_APPROVAL':
      return { status: 'awaiting_approval', activeTool: action.toolName, approvalPayload: action.payload, error: null };
    case 'APPROVE_AND_RESUME':
      return { ...state, status: 'executing', approvalPayload: null };
    case 'COMPLETE':
      return { status: 'completed', activeTool: null, approvalPayload: null, error: null };
    case 'FAIL':
      return { status: 'failed', activeTool: null, approvalPayload: null, error: action.error };
    default:
      return state;
  }
}

import { renderHook, act } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { useDebounce } from './useDebounce';

describe('useDebounce Hook', () => {
  beforeEach(() => { vi.useFakeTimers(); });
  afterEach(() => { vi.useRealTimers(); });

  it('should return initial value immediately and delay updates', () => {
    const { result, rerender } = renderHook(({ val, delay }) => useDebounce(val, delay), {
      initialProps: { val: 'alpha', delay: 300 },
    });

    expect(result.current).toBe('alpha');

    // Rerender with new value
    rerender({ val: 'beta', delay: 300 });
    expect(result.current).toBe('alpha'); // Still old value before timer

    // Fast-forward 300ms
    act(() => {
      vi.advanceTimersByTime(300);
    });

    expect(result.current).toBe('beta');
  });
});
